-- LOCAL REHEARSAL BODY (throwaway database; synthetic rows; everything rolls back). Run via rehearse.sh, AFTER the real 0168 SQL.
create temp table results (n serial, label text, pass boolean);
create temp table errs (n serial, msg text);
create function pg_temp.chk(l text, c boolean) returns void language sql as $$ insert into results(label, pass) values (l, coalesce(c, false)) $$;
create function pg_temp.fails(q text) returns boolean language plpgsql as $$ begin execute q; insert into errs(msg) values ('!! NO ERROR: ' || left(q, 90)); return false; exception when others then insert into errs(msg) values (sqlerrm); return true; end $$;

set local session_replication_role = replica;
insert into auth.users (id,email) values ('00000000-0000-4000-8000-0000000000a1','staff@rehearsal.test'),('00000000-0000-4000-8000-0000000000a2','founder@rehearsal.test') on conflict do nothing;
insert into public.profiles (id, full_name, access_status) values ('00000000-0000-4000-8000-0000000000a1','Staff','active'),('00000000-0000-4000-8000-0000000000a2','Founder','active') on conflict do nothing;
insert into public.user_roles (user_id, role_id) select '00000000-0000-4000-8000-0000000000a2', r.id from public.roles r where r.slug='super_admin' on conflict do nothing;
insert into public.enquiries (id, reference_number, email, full_name, service) values ('00000000-0000-4000-8000-00000000e001','ENQ-R-1','a@b.test','R One','photography'),('00000000-0000-4000-8000-00000000e002','ENQ-R-2','c@d.test','R Two','photography');
set local session_replication_role = origin;

-- discounts
insert into public.enquiry_discount_approvals (id, enquiry_id, scope_hash, scope_snapshot, eligible_base_usd, discount_type, discount_value, discount_usd, total_after_usd, reason, proposed_by)
 values ('00000000-0000-4000-8000-0000000d0001','00000000-0000-4000-8000-00000000e001',repeat('a',64),'{}',1000,'percentage',10,100,900,'loyal repeat client, agreed by phone','00000000-0000-4000-8000-0000000000a1');
select pg_temp.chk('discount: staff can propose', (select status from public.enquiry_discount_approvals where id='00000000-0000-4000-8000-0000000d0001')='proposed');
select pg_temp.chk('discount: arithmetic must hold', pg_temp.fails($q$insert into public.enquiry_discount_approvals (enquiry_id, scope_hash, scope_snapshot, eligible_base_usd, discount_type, discount_value, discount_usd, total_after_usd, reason, proposed_by) values ('00000000-0000-4000-8000-00000000e002',repeat('b',64),'{}',1000,'fixed',100,100,850,'wrong arithmetic here','00000000-0000-4000-8000-0000000000a1')$q$));
select pg_temp.chk('discount: a second live discount for the same enquiry is refused', pg_temp.fails($q$insert into public.enquiry_discount_approvals (enquiry_id, scope_hash, scope_snapshot, eligible_base_usd, discount_type, discount_value, discount_usd, total_after_usd, reason, proposed_by) values ('00000000-0000-4000-8000-00000000e001',repeat('c',64),'{}',1000,'fixed',50,50,950,'second discount attempt','00000000-0000-4000-8000-0000000000a1')$q$));
select pg_temp.chk('discount: staff cannot approve', pg_temp.fails($q$update public.enquiry_discount_approvals set status='approved', decided_by='00000000-0000-4000-8000-0000000000a1', decided_at=now() where id='00000000-0000-4000-8000-0000000d0001'$q$));
select pg_temp.chk('discount: terms cannot be edited after the fact', pg_temp.fails($q$update public.enquiry_discount_approvals set discount_usd=500, total_after_usd=500 where id='00000000-0000-4000-8000-0000000d0001'$q$));
-- a communication cannot carry an unapproved discount
select pg_temp.chk('communication: an unapproved discount cannot be carried', pg_temp.fails($q$insert into public.enquiry_price_communications (enquiry_id, service, market_slug, scope_title, scope_lines, pricing_snapshot, scope_hash, communicated_amount, channel, communicated_at, recorded_by, discount_approval_id) values ('00000000-0000-4000-8000-00000000e001','photography','ghana','Wedding','[]','{}',repeat('a',64),900,'phone',now(),'00000000-0000-4000-8000-0000000000a1','00000000-0000-4000-8000-0000000d0001')$q$));
update public.enquiry_discount_approvals set status='approved', decided_by='00000000-0000-4000-8000-0000000000a2', decided_at=now(), decision_note='ok' where id='00000000-0000-4000-8000-0000000d0001';
select pg_temp.chk('discount: a Super Admin approves', (select status from public.enquiry_discount_approvals where id='00000000-0000-4000-8000-0000000d0001')='approved');
select pg_temp.chk('communication: approved discount for a DIFFERENT scope is refused', pg_temp.fails($q$insert into public.enquiry_price_communications (enquiry_id, service, market_slug, scope_title, scope_lines, pricing_snapshot, scope_hash, communicated_amount, channel, communicated_at, recorded_by, discount_approval_id) values ('00000000-0000-4000-8000-00000000e001','photography','ghana','Wedding','[]','{}',repeat('f',64),900,'phone',now(),'00000000-0000-4000-8000-0000000000a1','00000000-0000-4000-8000-0000000d0001')$q$));
select pg_temp.chk('communication: approved discount for a DIFFERENT amount is refused', pg_temp.fails($q$insert into public.enquiry_price_communications (enquiry_id, service, market_slug, scope_title, scope_lines, pricing_snapshot, scope_hash, communicated_amount, channel, communicated_at, recorded_by, discount_approval_id) values ('00000000-0000-4000-8000-00000000e001','photography','ghana','Wedding','[]','{}',repeat('a',64),800,'phone',now(),'00000000-0000-4000-8000-0000000000a1','00000000-0000-4000-8000-0000000d0001')$q$));
select pg_temp.chk('communication: approval cannot be borrowed by another enquiry', pg_temp.fails($q$insert into public.enquiry_price_communications (enquiry_id, service, market_slug, scope_title, scope_lines, pricing_snapshot, scope_hash, communicated_amount, channel, communicated_at, recorded_by, discount_approval_id) values ('00000000-0000-4000-8000-00000000e002','photography','ghana','Wedding','[]','{}',repeat('a',64),900,'phone',now(),'00000000-0000-4000-8000-0000000000a1','00000000-0000-4000-8000-0000000d0001')$q$));
-- revisions
insert into public.enquiry_price_communications (enquiry_id, service, market_slug, scope_title, scope_lines, pricing_snapshot, scope_hash, original_total_usd, communicated_amount, channel, communicated_at, recorded_by) values ('00000000-0000-4000-8000-00000000e001','photography','ghana','Wedding','[]','{}',repeat('a',64),1000,1000,'phone',now(),'00000000-0000-4000-8000-0000000000a1');
insert into public.enquiry_price_communications (enquiry_id, service, market_slug, scope_title, scope_lines, pricing_snapshot, scope_hash, original_total_usd, communicated_amount, channel, communicated_at, recorded_by, discount_approval_id) values ('00000000-0000-4000-8000-00000000e001','photography','ghana','Wedding','[]','{}',repeat('a',64),1000,900,'whatsapp',now(),'00000000-0000-4000-8000-0000000000a1','00000000-0000-4000-8000-0000000d0001');
select pg_temp.chk('communication: revisions number themselves 1,2 and link to the previous one', (select string_agg(revision_number::text, ',' order by revision_number) from public.enquiry_price_communications where enquiry_id='00000000-0000-4000-8000-00000000e001')='1,2' and (select supersedes_id from public.enquiry_price_communications where revision_number=2 and enquiry_id='00000000-0000-4000-8000-00000000e001')=(select id from public.enquiry_price_communications where revision_number=1 and enquiry_id='00000000-0000-4000-8000-00000000e001'));
select pg_temp.chk('communication: original and revised amounts are both kept', (select original_total_usd||'>'||communicated_amount from public.enquiry_price_communications where revision_number=2 and enquiry_id='00000000-0000-4000-8000-00000000e001')='1000.00>900.00');
select pg_temp.chk('communication: history is append-only', pg_temp.fails('update public.enquiry_price_communications set communicated_amount = 1') and pg_temp.fails('delete from public.enquiry_price_communications'));
select pg_temp.chk('communication: a future-dated communication is refused', pg_temp.fails($q$insert into public.enquiry_price_communications (enquiry_id, service, market_slug, scope_title, scope_lines, pricing_snapshot, scope_hash, communicated_amount, channel, communicated_at, recorded_by) values ('00000000-0000-4000-8000-00000000e002','photography','ghana','W','[]','{}',repeat('a',64),500,'phone',now() + interval '2 days','00000000-0000-4000-8000-0000000000a1')$q$));
select pg_temp.chk('communication: indicative local currency needs its rate and date, all or none', pg_temp.fails($q$insert into public.enquiry_price_communications (enquiry_id, service, market_slug, scope_title, scope_lines, pricing_snapshot, scope_hash, communicated_amount, channel, communicated_at, recorded_by, indicative_local_currency, indicative_local_amount) values ('00000000-0000-4000-8000-00000000e002','photography','ghana','W','[]','{}',repeat('a',64),500,'phone',now(),'00000000-0000-4000-8000-0000000000a1','GHS',7000)$q$));
select pg_temp.chk('communication: revisions are serialised per enquiry by an advisory lock', (select prosrc like '%pg_advisory_xact_lock%' from pg_proc where proname='enquiry_comm_before_insert'));
-- follow-ups
insert into public.enquiry_followups (id, enquiry_id, handler_profile_id, next_action, due_at, created_by) values ('00000000-0000-4000-8000-0000000f0001','00000000-0000-4000-8000-00000000e001','00000000-0000-4000-8000-0000000000a1','Call to confirm the quote', now() - interval '2 days','00000000-0000-4000-8000-0000000000a2');
select pg_temp.chk('follow-up: only one open follow-up per enquiry', pg_temp.fails($q$insert into public.enquiry_followups (enquiry_id, handler_profile_id, next_action, due_at, created_by) values ('00000000-0000-4000-8000-00000000e001','00000000-0000-4000-8000-0000000000a1','Another one', now(),'00000000-0000-4000-8000-0000000000a2')$q$));
select pg_temp.chk('follow-up: due and overdue are findable by the index predicate', (select count(*) from public.enquiry_followups where status='open' and due_at < now())=1);
select pg_temp.chk('follow-up: cannot be edited in place', pg_temp.fails($q$update public.enquiry_followups set due_at = now() + interval '9 days' where id='00000000-0000-4000-8000-0000000f0001'$q$));
select pg_temp.chk('follow-up: rescheduling needs a reason', pg_temp.fails($q$select public.reschedule_enquiry_followup('00000000-0000-4000-8000-0000000f0001', now() + interval '3 days', '00000000-0000-4000-8000-0000000000a1', '')$q$));
select public.reschedule_enquiry_followup('00000000-0000-4000-8000-0000000f0001', now() + interval '3 days', '00000000-0000-4000-8000-0000000000a1', 'client asked us to call after the weekend', '00000000-0000-4000-8000-0000000000a2');
select pg_temp.chk('follow-up: rescheduling keeps history, keeps one open, and can hand over to another handler', (select count(*) from public.enquiry_followups where enquiry_id='00000000-0000-4000-8000-00000000e001')=2 and (select count(*) from public.enquiry_followups where enquiry_id='00000000-0000-4000-8000-00000000e001' and status='open')=1 and (select handler_profile_id from public.enquiry_followups where status='open' and enquiry_id='00000000-0000-4000-8000-00000000e001')='00000000-0000-4000-8000-0000000000a2' and (select status||':'||completion_note from public.enquiry_followups where id='00000000-0000-4000-8000-0000000f0001') like 'cancelled:Rescheduled: client asked%');
select pg_temp.chk('follow-up: a closed follow-up is final', pg_temp.fails($q$update public.enquiry_followups set status='open', completed_at=null, completed_by=null where id='00000000-0000-4000-8000-0000000f0001'$q$));
-- conversion
insert into public.enquiry_conversions (enquiry_id, target_type, target_id, idempotency_key, converted_by) values ('00000000-0000-4000-8000-00000000e001','client_quotation',gen_random_uuid(),'enquiry-convert:client_quotation:abcdef0123456789abcdef01','00000000-0000-4000-8000-0000000000a1');
select pg_temp.chk('conversion: a second conversion of the same enquiry is refused (no duplicate quotation)', pg_temp.fails($q$insert into public.enquiry_conversions (enquiry_id, target_type, target_id, idempotency_key, converted_by) values ('00000000-0000-4000-8000-00000000e001','client_quotation',gen_random_uuid(),'enquiry-convert:client_quotation:zzzzzzzzzzzzzzzzzzzzzzzz','00000000-0000-4000-8000-0000000000a1')$q$));
select pg_temp.chk('conversion: the same idempotency key cannot be reused', pg_temp.fails($q$insert into public.enquiry_conversions (enquiry_id, target_type, target_id, idempotency_key, converted_by) values ('00000000-0000-4000-8000-00000000e002','client_quotation',gen_random_uuid(),'enquiry-convert:client_quotation:abcdef0123456789abcdef01','00000000-0000-4000-8000-0000000000a1')$q$));
select pg_temp.chk('conversion: records are append-only', pg_temp.fails('update public.enquiry_conversions set target_id = gen_random_uuid()') and pg_temp.fails('delete from public.enquiry_conversions'));
select pg_temp.chk('RLS: enabled on every new table', (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('enquiry_discount_approvals','enquiry_price_communications','enquiry_followups','enquiry_conversions') and c.relrowsecurity)=4);
select pg_temp.chk('no existing enquiry row was touched', (select count(*) from public.enquiries where reference_number in ('ENQ-R-1','ENQ-R-2'))=2);

select n, case when pass then 'OK  ' else 'FAIL' end res, label from results order by n;
select 'REJECTION ' || n || ': ' || left(msg, 150) from errs order by n;
select 'SUMMARY ' || count(*) filter (where pass) || ' pass, ' || count(*) filter (where not pass) || ' fail' from results;
